// Identify client milestones
const clients = $node["Google Sheets - Get All Clients"].json;
const sessions = $node["Google Sheets - Get Session History"].json;
const achievements = $node["Google Sheets - Get Goal Achievements"].json;
const milestoneHistory = $node["Google Sheets - Get Milestone History"].json;

// Current date for calculations
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const todayStr = today.toISOString().split('T')[0];

// Create a map of client IDs to their session counts
const sessionCountMap = new Map();
sessions.forEach(session => {
  if (session.client_id) {
    if (!sessionCountMap.has(session.client_id)) {
      sessionCountMap.set(session.client_id, 0);
    }
    sessionCountMap.set(session.client_id, sessionCountMap.get(session.client_id) + 1);
  }
});

// Create a map of client IDs to their last milestone recognition date by type
const lastMilestoneMap = new Map();
milestoneHistory.forEach(milestone => {
  if (milestone.client_id && milestone.date && milestone.milestone_type) {
    const clientId = milestone.client_id;
    const milestoneType = milestone.milestone_type;
    const milestoneDate = new Date(milestone.date);

    if (!lastMilestoneMap.has(clientId)) {
      lastMilestoneMap.set(clientId, {});
    }

    const clientMilestones = lastMilestoneMap.get(clientId);
    if (!clientMilestones[milestoneType] || milestoneDate > new Date(clientMilestones[milestoneType])) {
      clientMilestones[milestoneType] = milestone.date;
    }
  }
});

// Find clients with milestones
const clientMilestones = [];

// 1. Session count milestones (5, 10, 25, 50, 100)
const sessionMilestones = [5, 10, 25, 50, 100];
clients.forEach(client => {
  // Skip inactive clients
  if (client.status && (client.status.toLowerCase() === 'inactive' || client.status.toLowerCase() === 'unsubscribed')) {
    return;
  }

  const clientId = client.id || client.client_id;
  if (!clientId) return;

  // Check session count milestones
  const sessionCount = sessionCountMap.get(clientId) || 0;
  const clientMilestoneHistory = lastMilestoneMap.get(clientId) || {};

  for (const milestoneSessions of sessionMilestones) {
    if (sessionCount === milestoneSessions) {
      const milestoneType = `session-${milestoneSessions}`;

      // Check if this milestone has already been recognized
      if (!clientMilestoneHistory[milestoneType]) {
        clientMilestones.push({
          clientId,
          firstName: client.first_name || client.firstName || '',
          lastName: client.last_name || client.lastName || '',
          email: client.email || '',
          phone: client.phone || '',
          coachingType: client.coaching_type || client.coachingType || 'General',
          milestoneType,
          milestoneValue: milestoneSessions,
          milestoneCategory: 'session-count',
          description: `Completed ${milestoneSessions} coaching sessions`
        });
      }
    }
  }

  // 2. Anniversary milestones (30 days, 90 days, 6 months, 1 year)
  const createdDate = client.created_date || client.createdDate;
  if (createdDate) {
    const clientCreatedDate = new Date(createdDate);
    const daysSinceCreation = Math.floor((today - clientCreatedDate) / (1000 * 60 * 60 * 24));

    // Check for anniversaries
    const anniversaryMilestones = [
      { days: 30, type: 'anniversary-30-days' },
      { days: 90, type: 'anniversary-90-days' },
      { days: 180, type: 'anniversary-6-months' },
      { days: 365, type: 'anniversary-1-year' },
      { days: 730, type: 'anniversary-2-years' }
    ];

    for (const milestone of anniversaryMilestones) {
      if (daysSinceCreation === milestone.days) {
        // Check if this milestone has already been recognized
        if (!clientMilestoneHistory[milestone.type]) {
          let description = '';
          if (milestone.days === 30) description = '30 days of coaching partnership';
          else if (milestone.days === 90) description = '90 days of coaching partnership';
          else if (milestone.days === 180) description = '6 months of coaching partnership';
          else if (milestone.days === 365) description = '1 year of coaching partnership';
          else if (milestone.days === 730) description = '2 years of coaching partnership';

          clientMilestones.push({
            clientId,
            firstName: client.first_name || client.firstName || '',
            lastName: client.last_name || client.lastName || '',
            email: client.email || '',
            phone: client.phone || '',
            coachingType: client.coaching_type || client.coachingType || 'General',
            milestoneType: milestone.type,
            milestoneValue: milestone.days,
            milestoneCategory: 'anniversary',
            description
          });
        }
      }
    }
  }
});

// 3. Goal achievement milestones
achievements.forEach(achievement => {
  if (achievement.client_id && achievement.achievement_date && achievement.achievement_date === todayStr) {
    const clientId = achievement.client_id;

    // Find client details
    const client = clients.find(c => (c.id || c.client_id) === clientId);
    if (!client) return;

    // Skip inactive clients
    if (client.status && (client.status.toLowerCase() === 'inactive' || client.status.toLowerCase() === 'unsubscribed')) {
      return;
    }

    const milestoneType = `goal-${achievement.goal_id || 'achievement'}`;
    const clientMilestoneHistory = lastMilestoneMap.get(clientId) || {};

    // Check if this specific goal achievement has already been recognized
    if (!clientMilestoneHistory[milestoneType]) {
      clientMilestones.push({
        clientId,
        firstName: client.first_name || client.firstName || '',
        lastName: client.last_name || client.lastName || '',
        email: client.email || '',
        phone: client.phone || '',
        coachingType: client.coaching_type || client.coachingType || 'General',
        milestoneType,
        milestoneValue: achievement.goal_id || '',
        milestoneCategory: 'goal-achievement',
        description: achievement.achievement_description || 'Goal achievement',
        goalDetails: achievement.goal_details || ''
      });
    }
  }
});

return {
  totalMilestones: clientMilestones.length,
  milestones: clientMilestones
};

// Process each milestone individually
const milestones = $node["Code - Identify Milestones"].json.milestones;
const currentIndex = $input.item.index;

if (currentIndex < milestones.length) {
  return milestones[currentIndex];
} else {
  return {};
}

values.content:
=Create a personalized congratulatory email for a client who has reached a milestone with the following details:

Client Name: {{$node["Code - Process Each Milestone"].json["firstName"]}} {{$node["Code - Process Each Milestone"].json["lastName"]}}
Coaching Type: {{$node["Code - Process Each Milestone"].json["coachingType"]}}
Milestone: {{$node["Code - Process Each Milestone"].json["description"]}}
{% if $node["Code - Process Each Milestone"].json["milestoneCategory"] === 'goal-achievement' %}
Goal Details: {{$node["Code - Process Each Milestone"].json["goalDetails"]}}
{% endif %}

The email should:
1. Be celebratory and enthusiastic
2. Acknowledge their specific achievement
3. Highlight the significance of this milestone
4. Encourage continued progress
5. Express genuine appreciation for their commitment
6. Be written in a conversational, personal tone

The email should be formatted in HTML for a Gmail message.
